const specs = [
  ["tome-cults.lua", "打开了房间的窗户，发现远处的大楼", "打开了房间的窗户，发现远处的大楼", "我向房间窗外望去，看见远处的大楼"],
  ["tome-cults.lua", "奇异而且很不健全的生物", "奇异而且很不健全的生物", "奇异、多半并非善类的生物"],
  ["tome-cults.lua", "酒馆的木制路标", "酒馆的木制路标", "酒馆的木招牌"],
];
for (const [file, needle, oldText, newText] of specs) {
  const q = needle.replace(/'/g, "'\\''");
  const got = await tools.exec_command({cmd:`rg -n -F '${q}' ${file}`, workdir:"/workspace/tome4-chinese-translation", yield_time_ms:10000, max_output_tokens:12000, sandbox_permissions:"require_escalated", justification:"允许我读取目标所在完整行，以通过 apply_patch 进行精确单行替换吗？", prefix_rule:["rg","-n"]});
  const lines = got.output.trimEnd().split("\n");
  if (lines.length !== 1) throw new Error(`${needle}: expected 1 line, got ${lines.length}`);
  const oldLine = lines[0].replace(/^\d+:/, "");
  let newLine = oldLine.replace(oldText, newText);
  if (needle === "酒馆的木制路标") newLine = newLine.replace("路标旁边的房子", "招牌旁边的房子");
  if (newLine === oldLine) throw new Error(`${needle}: replacement failed`);
  const patch = `*** Begin Patch\n*** Update File: /workspace/tome4-chinese-translation/${file}\n@@\n-${oldLine}\n+${newLine}\n*** End Patch`;
  await tools.apply_patch(patch);
}
const tabPatch = "*** Begin Patch\n*** Update File: /workspace/tome4-chinese-translation/tome-ashes-urhrok.lua\n@@\n-\t\t当你处于强化状态下，无法施加新的悲惨结局效果。\n+\t\t当你处于强化状态下，无法施加新的悲惨结局效果。\t\t\n*** End Patch";
text(await tools.apply_patch(tabPatch));

